INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (23162, "もうこの辺で……", "挑戦終了", 105501, "62_ayumi_sad", 23162, 0, 0);
